    poet:`கல்லாடனார்`, poetEnglish:`Kallāṭaṉār`,
    speaker:`தலைவன்`, speakerEnglish:`The hero, at the shore`,
    turai:`இரவு தனிமை கூறியது`, turaiEnglish:`Speaking of the night's loneliness`,
