    turai:`மறுத்தது`, turaiEnglish:`Withholding forgiveness`,
    tamil:`வேல் கண்ணாள் விழி வாடியது
துளி மழை போல் கண்ணீர் சோர்ந்தது
கலை வேங்கை காட்டில் போல் ஒளிந்தான்
மலை நாட்டான் மாறினான் என்றாள்`, transliteration:`Vēl kaṇṇāḷ viḻi vāṭiyatu
tuḷi maḻai pōl kaṇṇīr cōrntatu
kalai vēṅkai kāṭṭil pōl oḷintāṉ
malai nāṭṭāṉ māṟiṉāṉ eṉṟāḷ`,
    english:`Her spear-eyes have withered.
Tears flowed like drops of rain.
'He hid like a deer in the vēṅkai forest —
the mountain-country man has changed,' she said.`, tamilUrai:`வேல் கண்ணாள் விழிகள் வாடின. துளி மழை போல் கண்ணீர் சோர்ந்தது. 'கலை வேங்கை காட்டில் போல் ஒளிந்தான் — மலை நாட்டான் மாறினான்' என்றாள்.`,
    altTranslation:`Her spear-eyes have withered. Tears flowed like drops of rain. 'He hid like a deer in the vēṅkai forest — the mountain-country man has changed,' she said.`, note:`The withering of the 'spear-eyes' — previously a figure of beauty and power — into grief is a characteristic Sangam inversion: the very attributes of strength become signs of suffering. 'He hid like a deer in the vēṅkai forest' — the deer hides from hunters; the hero hides from the heroine's just anger. She names what has happened directly: 'he has changed.'`
