    altTranslation:`Her spear-eyes have withered. Tears flowed like drops of rain. 'He hid like a deer in the vēṅkai forest — the mountain-country man has changed,' she said.`, note:`The withering of the 'spear-eyes' — previously a figure of beauty and power — into grief is a characteristic Sangam inversion: the very attributes of strength become signs of suffering. 'He hid like a deer in the vēṅkai forest' — the deer hides from hunters; the hero hides from the heroine's just anger. She names what has happened directly: 'he has changed.'`
