    altTranslation:`At the time of rains, the forest where deer dance — at the time of the chariot's coming, inexhaustible joy — the jasmine that comes to the village, like fate — my long-haired friend has grieved.`, note:`The poem moves through conditional structures: at the time when… but the conditionals are not fulfilled — the chariot has not come, the joy remains potential. The jasmine that arrives like fate (ūḻviṉai) — inevitable, unwilled — brings not comfort but the reminder of what is absent.`
