    altTranslation:`Earth and water and fire and wind — many things he crossed in his journey. The strong one came, the path he crossed — even the turbulence of the sea-country has calmed.`, note:`The four elements (earth, water, fire, wind) as obstacles crossed by the returning hero give the journey cosmic scale. The sea-country whose 'turbulence' (kali) calms echoes the Paripaāṭal's language — the world's disturbance settling when the beloved returns. Even the sea participates in the resolution.`
